import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-biochemistry-foundations-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`What drives protein folding in water?`]: {
    question: r`A mutation in a water-soluble cytosolic enzyme replaces a valine buried in the protein's core with aspartate. What is the most likely effect on the folded structure?`,
    options: [r`It is stabilized, because a charged side chain bonds strongly to nonpolar groups`, r`It is unchanged, because only backbone hydrogen bonds set the tertiary structure`, r`It is destabilized, because a charged side chain resists burial away from water`, r`It is unchanged, because peptide bonds rather than side chains hold the core`],
    correctAnswer: 2,
    explanation: r`Folding in water is driven by burying nonpolar side chains in the core, so putting a charged aspartate where valine sat removes that drive and destabilizes the fold. A charge does not bond well to nonpolar neighbors. Backbone hydrogen bonds shape helices and sheets but do not decide which residues pack inside, and peptide bonds only link the sequence.`,
  },
  [r`What is $K_m$ and what does a low value mean?`]: {
    question: r`A wild-type enzyme reaches 40 μmol/min at saturating substrate and runs at 20 μmol/min when substrate is 0.5 mM. A mutant has the same maximum rate but needs 5 mM substrate to reach 20 μmol/min. Which statement about the mutant is correct?`,
    options: [r`Its Km is 5 mM, so its apparent affinity for substrate is lower`, r`Its Km is 5 mM, so its apparent affinity for substrate is higher`, r`Its Km is 2.5 mM, so its apparent affinity for substrate is lower`, r`Its Km is 10 mM, so its apparent affinity for substrate is lower`],
    correctAnswer: 0,
    explanation: r`Km is the substrate concentration that gives half of Vmax, and 20 is half of 40, so the mutant's Km is 5 mM against 0.5 mM for the wild type. A higher Km means more substrate is needed, which is lower apparent affinity, not higher. The values 2.5 mM and 10 mM come from halving or doubling the concentration instead of reading it off at half of Vmax.`,
  },
  [r`List the four levels of protein structure.`]: {
    question: r`A structural report on an enzyme makes three statements: (1) residue 42 is serine; (2) residues 10 to 25 form an alpha-helix; (3) that helix packs against a beta-sheet in the same chain. Which levels of protein structure do the statements describe, in order?`,
    options: [r`primary, tertiary, quaternary`, r`secondary, tertiary, quaternary`, r`primary, secondary, tertiary`, r`primary, secondary, quaternary`],
    correctAnswer: 2,
    explanation: r`The identity of a residue is sequence (primary), a helix is a local backbone hydrogen-bonded pattern (secondary), and the packing of a helix against a sheet within one chain is the three-dimensional fold (tertiary). Any answer that includes quaternary is wrong because only one chain is involved. Calling the helix tertiary confuses local backbone structure with the overall fold.`,
  },
  [r`Why do cooperative enzymes show sigmoidal kinetics?`]: {
    question: r`A four-subunit enzyme normally shows a sigmoidal plot of velocity against substrate concentration. A mutation stops the subunits from passing conformational changes to one another, although each active site still binds substrate. What shape is the plot now?`,
    options: [r`Hyperbolic, because each site now binds substrate independently`, r`Sigmoidal, because each site now binds substrate independently`, r`Hyperbolic, because one bound site now raises affinity at others`, r`Linear, because velocity no longer levels off at high substrate`],
    correctAnswer: 0,
    explanation: r`The sigmoidal curve comes from positive cooperativity: binding at one subunit raises affinity at the others. Without communication between subunits each site behaves alone, which gives the ordinary hyperbolic curve. Independent sites cannot give a sigmoid, raising affinity at other sites is the cooperativity that was lost, and the enzyme still saturates so the plot is not linear.`,
  },
  [r`How do competitive and noncompetitive inhibitors differ kinetically?`]: {
    question: r`An enzyme has Vmax = 100 μmol/min and Km = 2 mM. With inhibitor X the values become Vmax = 100 μmol/min and Km = 6 mM. With inhibitor Y instead they become Vmax = 40 μmol/min and Km = 2 mM. How should X and Y be classified?`,
    options: [r`X is noncompetitive and Y is competitive`, r`X is uncompetitive and Y is competitive`, r`X is competitive and Y is noncompetitive`, r`X is competitive and Y is uncompetitive`],
    correctAnswer: 2,
    explanation: r`X raises Km and leaves Vmax alone, the competitive pattern, while Y lowers Vmax and leaves Km alone, the noncompetitive pattern. Swapping the two labels reverses those signatures. An uncompetitive inhibitor lowers both Vmax and Km, which matches neither data set.`,
  },
  [r`What is the pI of a protein?`]: {
    question: r`A protein with a pI of 5.0 is fully dissolved at pH 8.0. Acid is then added slowly. Near which pH is the protein most likely to come out of solution?`,
    options: [r`pH 5.0, where its net charge is zero`, r`pH 7.0, where the solution is neutral`, r`pH 2.0, where its charge is most positive`, r`pH 8.0, where its charge is most negative`],
    correctAnswer: 0,
    explanation: r`At the pI the protein has no net charge, so molecules stop repelling each other and solubility is at its minimum. pH 7.0 is neutral for water, not for this protein, which still carries a net negative charge there. At pH 2.0 and pH 8.0 the protein carries a large net charge, and that repulsion keeps it dissolved.`,
  },
  [r`Why does denaturation abolish enzyme function?`]: {
    question: r`An enzyme is heated until it loses all activity. The sample is then analyzed by mass spectrometry and by amino acid sequencing. Compared with the active enzyme, the heated enzyme shows:`,
    options: [r`the same mass and sequence, with an intact active-site shape`, r`a lower mass, because heat hydrolyzed its peptide bonds`, r`a new sequence, because heat rearranged its peptide bonds`, r`the same mass and sequence, but a disrupted active-site shape`],
    correctAnswer: 3,
    explanation: r`Denaturation unfolds secondary and tertiary structure, which destroys the geometry of the active site, but it leaves the covalent peptide backbone alone, so mass and sequence do not change. An intact active site would still be active. A lower mass or an altered sequence would need peptide bonds to break, which ordinary heat denaturation does not do.`,
  },
  [r`What form do amino acids take at physiological pH?`]: {
    question: r`Glycine has a carboxyl group with a pKa of 2.3 and an amino group with a pKa of 9.6. Which form of glycine predominates in a solution at pH 7?`,
    options: [r`H₂N-CH₂-COOH, with a net charge of 0`, r`⁺H₃N-CH₂-COOH, with a net charge of +1`, r`H₂N-CH₂-COO⁻, with a net charge of −1`, r`⁺H₃N-CH₂-COO⁻, with a net charge of 0`],
    correctAnswer: 3,
    explanation: r`pH 7 is above the carboxyl pKa, so that group has lost its proton, and below the amino pKa, so that group keeps its proton: the zwitterion, with one positive and one negative charge and a net charge of zero. The uncharged H₂N/COOH form has both groups in the wrong state. The +1 form exists only below pH 2.3 and the −1 form only above pH 9.6.`,
  },
  [r`Ketone bodies are produced during:`]: {
    question: r`Blood beta-hydroxybutyrate, a ketone body, is measured in four healthy adults. Which adult is expected to have the highest level?`,
    options: [r`one 1 hour after a large pasta meal`, r`one 30 seconds into an all-out sprint`, r`one on day 4 of a water-only fast`, r`one 4 hours after a mixed breakfast`],
    correctAnswer: 2,
    explanation: r`Ketone bodies are made when prolonged fasting or carbohydrate restriction sends a flood of acetyl-CoA from fat breakdown to the liver, so the adult four days into a fast has the highest level. After a pasta meal insulin is high and fat breakdown is suppressed. A short sprint runs on phosphocreatine and glycolysis, and four hours after breakfast liver glycogen still covers glucose needs.`,
  },
  [r`Disulfide bonds form between which amino acid residues?`]: {
    question: r`A secreted protein loses a covalent cross-link between two distant parts of its chain when it is treated with the reducing agent beta-mercaptoethanol. Replacing which pair of residues with alanine would remove the same cross-link?`,
    options: [r`two methionine residues`, r`two serine residues`, r`two lysine residues`, r`two cysteine residues`],
    correctAnswer: 3,
    explanation: r`A covalent cross-link that a reducing agent breaks is a disulfide bond, formed by oxidation of the thiol groups of two cysteines. Methionine contains sulfur but as a thioether with no free thiol, so it cannot form a disulfide. Serine has a hydroxyl and lysine an amine, and neither makes a link that a reducing agent would break.`,
  },
  [r`HDL is considered "good" cholesterol because it:`]: {
    question: r`A patient has a genetic defect that leaves the blood with almost no functional HDL particles. Which process is most directly impaired?`,
    options: [r`delivery of dietary triacylglycerol from the intestine to tissues`, r`delivery of liver-made cholesterol out to the peripheral tissues`, r`return of excess cholesterol from peripheral tissues to the liver`, r`export of liver-made triacylglycerol to adipose and muscle`],
    correctAnswer: 2,
    explanation: r`HDL carries out reverse cholesterol transport: it picks up cholesterol from peripheral tissues and returns it to the liver, which is why it is called good cholesterol. Carrying dietary triacylglycerol from the intestine is the job of chylomicrons. Delivering cholesterol outward to tissues is done by LDL, and exporting liver triacylglycerol is done by VLDL.`,
  },
  [r`Why does enzyme activity fall above the temperature optimum?`]: {
    question: r`A human enzyme has a temperature optimum of 37 °C. Its rate is lower at 27 °C and also lower at 60 °C. Which pair of reasons is correct?`,
    options: [r`27 °C: active site unfolded; 60 °C: fewer effective collisions`, r`27 °C: fewer effective collisions; 60 °C: peptide bonds broken`, r`27 °C: fewer effective collisions; 60 °C: active site unfolded`, r`27 °C: peptide bonds broken; 60 °C: active site unfolded`],
    correctAnswer: 2,
    explanation: r`Below the optimum the enzyme is intact and the rate simply follows temperature, so cooler means fewer collisions with enough energy. Above the optimum thermal denaturation unfolds the active site. Reversing the two reasons puts unfolding at the cool end, and heat at 60 °C disrupts noncovalent structure, not the peptide bonds.`,
  },
  [r`Quaternary structure refers to:`]: {
    question: r`Which of these proteins cannot have quaternary structure?`,
    options: [r`hemoglobin, two alpha chains and two beta chains together`, r`an antibody, two heavy chains joined to two light chains`, r`myoglobin, a single polypeptide chain carrying one heme`, r`collagen, three polypeptide chains wound around each other`],
    correctAnswer: 2,
    explanation: r`Quaternary structure is the assembly of two or more polypeptide subunits, so a protein made of one chain, such as myoglobin, stops at tertiary structure. Hemoglobin with four chains, an antibody with four chains and collagen with three chains all have subunits arranged together, which is quaternary structure by definition.`,
  },
  [r`At physiological pH (7.4), a typical amino acid exists as a:`]: {
    question: r`At pH 7.4, free aspartate has its alpha-amino and alpha-carboxyl groups in the usual zwitterion states, and its side chain is a carboxyl group with a pKa near 4. What is the net charge on the molecule?`,
    options: [r`−1: the backbone charges cancel and the side chain is COO⁻`, r`0: the backbone charges cancel and the side chain is COOH`, r`−2: both carboxyls are COO⁻ and the amino group is NH₂`, r`+1: the amino group is NH₃⁺ and both carboxyls are COOH`],
    correctAnswer: 0,
    explanation: r`The zwitterion backbone contributes +1 from NH₃⁺ and −1 from COO⁻, which cancel, so the net charge is set by the side chain. At pH 7.4, well above a pKa of 4, the side-chain carboxyl is deprotonated and adds −1. A charge of 0 forgets the side chain, −2 wrongly removes the proton from the amino group, and +1 wrongly keeps protons on both carboxyls.`,
  },
  [r`Allosteric regulation involves binding:`]: {
    question: r`CTP, the end product of pyrimidine synthesis, inhibits aspartate transcarbamoylase, the first enzyme of the pathway. CTP does not resemble either substrate of the enzyme. What is the most likely mechanism?`,
    options: [r`CTP binds in the active site and competes directly with the two substrates`, r`CTP binds in the active site and forms a covalent bond with a key residue`, r`CTP binds the free substrates in solution and lowers their concentration`, r`CTP binds a separate regulatory site and changes the enzyme's conformation`],
    correctAnswer: 3,
    explanation: r`Feedback inhibition by an end product that looks nothing like the substrate is the classic allosteric case: the regulator binds a site other than the active site and a conformational change lowers activity. Competing in the active site requires a molecule that resembles the substrate. Covalent attack on the active site and binding to free substrate are not how end-product feedback works.`,
  },
  [r`Vitamin B12 works in exactly two human enzymes: {{c1::methylmalonyl-CoA mutase}} and {{c2::methionine synthase}} — the latter explains the folate {{c3::trap}}.`]: {
    question: r`A patient with megaloblastic anemia and numbness in both feet is found to be deficient in vitamin B12. Which pair of blood findings is expected?`,
    options: [r`normal methylmalonic acid and high homocysteine`, r`high methylmalonic acid and normal homocysteine`, r`normal methylmalonic acid and low homocysteine`, r`high methylmalonic acid and high homocysteine`],
    correctAnswer: 3,
    explanation: r`B12 serves two enzymes, so both substrates back up: methylmalonyl-CoA mutase stalls and methylmalonic acid rises, and methionine synthase stalls and homocysteine rises. Normal methylmalonic acid with high homocysteine is the folate deficiency pattern, which lacks the neurologic signs. The other two options ignore the block at methionine synthase, where homocysteine cannot be remethylated.`,
  },
  [r`Which hydroxylation reactions require vitamin C, and what is its chemical role there?`]: {
    question: r`Fibroblasts grown without ascorbate secrete collagen chains that cannot form stable triple helices. Which statement best explains the defect?`,
    options: [r`Proline hydroxylation fails, because the enzyme's iron is left as Fe²⁺`, r`Glycine methylation fails, because the enzyme's iron is left as Fe³⁺`, r`Lysine acetylation fails, because the enzyme's iron is left as Fe²⁺`, r`Proline hydroxylation fails, because the enzyme's iron is left as Fe³⁺`],
    correctAnswer: 3,
    explanation: r`Prolyl and lysyl hydroxylases need their iron in the reduced Fe²⁺ state, and ascorbate is what keeps it reduced; without it the iron stays oxidized as Fe³⁺ and hydroxyproline is not made. Fe²⁺ is the working state, not the failed one. Vitamin C is not involved in methylating glycine or acetylating lysine, and neither is a step of collagen maturation.`,
  },
  [r`Trace the life cycle of cAMP: what makes it, what destroys it, and how do methylxanthines like caffeine perturb the system?`]: {
    question: r`Liver cells are given a small dose of glucagon, with or without theophylline, a methylxanthine related to caffeine. How does theophylline change the cAMP response?`,
    options: [r`cAMP stays high longer, because adenylyl cyclase is switched off`, r`cAMP stays high longer, because phosphodiesterase is inhibited`, r`cAMP falls sooner, because phosphodiesterase is activated`, r`cAMP falls sooner, because adenylyl cyclase is inhibited by Gs`],
    correctAnswer: 1,
    explanation: r`Phosphodiesterase ends the signal by hydrolyzing cAMP to AMP, and methylxanthines inhibit it, so cAMP persists and the glucagon effect is amplified. Switching off adenylyl cyclase would lower cAMP, not prolong it. Activating phosphodiesterase is the opposite of what the drug does, and Gs activates the cyclase.`,
  },
  [r`How is S-adenosylmethionine formed, and what regenerates methionine after the methyl group is donated?`]: {
    question: r`S-adenosylmethionine is made from methionine and ATP whose alpha phosphate carries a ³²P label. Where is the label found after the reaction?`,
    options: [r`In the SAM product, because SAM keeps the alpha phosphate as AMP does`, r`In released ADP, because only the gamma phosphate is split from ATP`, r`In the released PPi, because SAM keeps none of ATP's three phosphates`, r`In the sulfur of SAM, because the phosphate is passed on to that atom`],
    correctAnswer: 2,
    explanation: r`Methionine's sulfur attacks the 5' carbon of ATP and displaces all three phosphates, which leave as PPi (the alpha and beta phosphates) and Pi (the gamma phosphate), so SAM contains adenosine but no phosphate and the alpha label ends up in the released PPi. Keeping the alpha phosphate would describe an adenylyl (AMP) transfer. Releasing ADP describes an ordinary kinase reaction, and no phosphate is ever attached to the sulfur.`,
  },
  [r`Adenylate kinase makes {{c1::AMP}} an amplified low-energy signal, sensed chiefly by {{c2::AMPK}}.`]: {
    question: r`In a hard-working muscle cell, ATP falls by about 10%, from 5.0 mM to 4.5 mM, while adenylate kinase stays at equilibrium. What happens to AMP, and what follows?`,
    options: [r`AMP rises several-fold, and AMPK is activated`, r`AMP rises by about 10%, and AMPK is activated`, r`AMP falls several-fold, and AMPK is inhibited`, r`AMP falls by about 10%, and AMPK is inhibited`],
    correctAnswer: 0,
    explanation: r`Adenylate kinase converts 2 ADP into ATP and AMP, and because AMP starts very low, a small fractional fall in ATP shows up as a much larger fractional rise in AMP, which switches on AMPK. A 10% rise treats AMP as if it tracked ATP one for one. AMP does not fall when ATP is being used up, so both options with falling AMP have the direction wrong.`,
  },
  [r`Storing glucose as {{c1::glycogen}} avoids the {{c2::osmotic}} catastrophe that an equivalent amount of free glucose would cause in the cytosol.`]: {
    question: r`A liver cell holds glycogen equal to 400 mM of glucose units. Suppose all of it were suddenly hydrolyzed to free glucose that stayed in the cytosol. What is the immediate consequence?`,
    options: [r`Water leaves and the cell shrinks, since solute particles rise sharply`, r`Water enters and the cell swells, since solute particles rise sharply`, r`Water enters and the cell swells, since solute particles fall sharply`, r`Cell volume is unchanged, since the mass of glucose stays the same`],
    correctAnswer: 1,
    explanation: r`Osmotic pressure depends on the number of dissolved particles, and a glycogen granule counts as one particle no matter how many glucose units it holds. Freeing them raises cytosolic osmolarity enormously, so water rushes in and the cell swells. More solute inside pulls water in, not out, the particle count rises instead of falling, and mass is not what sets osmotic pressure.`,
  },
  [r`The hydrophobic effect is driven mainly by {{c1::entropy}}: aggregation of nonpolar groups releases ordered {{c2::water}} molecules from clathrate-like shells.`]: {
    question: r`Small oil droplets dispersed in water merge spontaneously into one large droplet. What is the main thermodynamic driving force?`,
    options: [r`Water entropy falls as bulk water is ordered into new shell cages`, r`Water entropy rises as ordered shell water is released to the bulk`, r`Oil enthalpy falls sharply as strong oil-oil attractions are formed`, r`Oil entropy rises as the oil molecules gather into a single droplet`],
    correctAnswer: 1,
    explanation: r`Merging droplets shrinks the nonpolar surface exposed to water, releasing water molecules from ordered cages and raising solvent entropy, which is the hydrophobic effect. Ordering more water would lower entropy and oppose merging. Attractions between nonpolar molecules are weak dispersion contacts and are secondary, and gathering the oil into one droplet lowers the oil's own entropy.`,
  },
  [r`A buffer resists pH change best within about {{c1::1 pH unit}} of its {{c2::$pK_a$}}, where the Henderson-Hasselbalch ratio stays near {{c3::1}}.`]: {
    question: r`An experiment needs a buffer that holds pH 7.8. Four buffers are available at equal concentration. Which one will resist pH change best?`,
    options: [r`Tris, with a pKa of 8.1`, r`MES, with a pKa of 6.1`, r`CAPS, with a pKa of 10.4`, r`acetate, with a pKa of 4.8`],
    correctAnswer: 0,
    explanation: r`A buffer works best within about one pH unit of its pKa, where acid and conjugate base are both present in useful amounts, and Tris is only 0.3 units from the target. MES is 1.7 units below, CAPS 2.6 units above and acetate 3.0 units below, so each is almost entirely in one form at pH 7.8 and has little capacity left.`,
  },
  [r`Bicarbonate ($pK_a$ {{c1::6.1}}) buffers blood well as an {{c2::open}} system: lungs vent $CO_2$, kidneys set {{c3::$HCO_3^-$}}.`]: {
    question: r`Equal amounts of strong acid are added to blood in a living person and to blood sealed in a gas-tight syringe. The pH of the sealed sample falls much more. Why?`,
    options: [r`The CO₂ produced leaves the sample, so the acid component runs out`, r`The pKa of 6.1 moves farther from 7.4 once the sample is sealed`, r`The CO₂ produced stays in the sample, so the acid component builds up`, r`The HCO₃⁻ consumed is replaced by the kidneys only in the sample`],
    correctAnswer: 2,
    explanation: r`Added H⁺ combines with HCO₃⁻ to make carbonic acid and CO₂. In the body the lungs vent that CO₂, keeping the acid component low, which is what makes bicarbonate an effective open system despite a pKa of 6.1. In a sealed sample the CO₂ is trapped, so the acid form accumulates and pH drops. Sealing does not change the pKa, CO₂ cannot leave a sealed syringe, and no kidney acts on it.`,
  },
  [r`How do you compute the isoelectric point of a simple amino acid versus an acidic or basic one?`]: {
    question: r`Aspartate has pKa values of 2.1 for the alpha-carboxyl group, 3.9 for the side-chain carboxyl group and 9.8 for the alpha-amino group. What is its isoelectric point?`,
    options: [r`6.85`, r`5.95`, r`5.27`, r`3.00`],
    correctAnswer: 3,
    explanation: r`For an acidic amino acid the neutral species sits between the two most acidic pKa values, so pI = (2.1 + 3.9)/2 = 3.00. The value 6.85 averages the side chain with the amino group, 5.95 uses the carboxyl and amino values as if aspartate were glycine, and 5.27 averages all three pKa values.`,
  },
  [r`$\Delta G = \Delta G^{\circ\prime} + RT\ln Q$: a positive {{c1::$\Delta G^{\circ\prime}$}} step proceeds if {{c2::Q}} is kept low.`]: {
    question: r`A reaction A → B has $\Delta G^{\circ\prime}$ = +5.7 kJ/mol at 25 °C, where RT ln 10 = 5.7 kJ/mol. In a cell the ratio [B]/[A] is held at 0.01. What is $\Delta G$, and which way does the reaction run?`,
    options: [r`+17.1 kJ/mol, so it runs in reverse`, r`+5.7 kJ/mol, so it runs in reverse`, r`−11.4 kJ/mol, so it runs forward`, r`−5.7 kJ/mol, so it runs forward`],
    correctAnswer: 3,
    explanation: r`Q = 0.01, so RT ln Q is 5.7 × (−2) = −11.4 kJ/mol, and ΔG = +5.7 − 11.4 = −5.7 kJ/mol: keeping product low makes a standard-unfavorable step run forward. +17.1 adds the Q term with the wrong sign. +5.7 ignores Q and uses the standard value, and −11.4 is the Q term alone without the standard value.`,
  },
  [r`State the relationship between the standard free energy change and the equilibrium constant, and what a tenfold change in $K_{eq}$ is worth at 25 °C.`]: {
    question: r`A reaction has $\Delta G^{\circ\prime}$ = −11.4 kJ/mol at 25 °C, where each factor of 10 in the equilibrium constant is worth 5.7 kJ/mol. What is $K_{eq}$?`,
    options: [r`about 0.01`, r`about 100`, r`about 20`, r`about 2`],
    correctAnswer: 1,
    explanation: r`From ΔG°′ = −RT ln Keq, −11.4 kJ/mol is two steps of 5.7 kJ/mol, so Keq = 10² = 100, with products favored because the sign is negative. The value 0.01 has the sign backward. The values 20 and 2 treat the relationship as linear, multiplying or dividing instead of using a power of ten.`,
  },
  [r`Why are digestive proteases and caspases made as zymogens, and what distinguishes this from phosphorylation control?`]: {
    question: r`Trypsinogen is activated to trypsin when a protease cuts off a short peptide from its N-terminus. Once trypsin is active, how can its activity be shut down?`,
    options: [r`A phosphatase must act on it, since the cut added a phosphate group`, r`A ligase must rejoin the peptide, since the cut is readily reversed`, r`A kinase must act on it, since the cut removed a phosphate group`, r`An inhibitor protein must bind it, since the cut cannot be reversed`],
    correctAnswer: 3,
    explanation: r`Zymogen activation is proteolytic cleavage, an irreversible commitment, so the only way to stop the active protease is to block or destroy it, which is the job of protease inhibitors such as SERPINs. Kinases and phosphatases belong to phosphorylation control, which is reversible and involves no cleavage. Cells do not rejoin the removed peptide.`,
  },
  [r`What makes energetic coupling through a shared intermediate legitimate, and give the textbook glutamine example.`]: {
    question: r`Glutamate + NH₃ → glutamine has $\Delta G^{\circ\prime}$ = +14 kJ/mol, and ATP hydrolysis has $\Delta G^{\circ\prime}$ = −30.5 kJ/mol. Glutamine synthetase uses ATP to make glutamine. What is the overall $\Delta G^{\circ\prime}$, and why does the coupling work?`,
    options: [r`−44.5 kJ/mol; glutamyl phosphate is an intermediate shared by both steps`, r`−16.5 kJ/mol; glutamyl phosphate is an intermediate shared by both steps`, r`−16.5 kJ/mol; heat released by ATP hydrolysis speeds up the second step`, r`+14 kJ/mol; ATP only lowers the activation energy of amide bond formation`],
    correctAnswer: 1,
    explanation: r`Standard free energies of sequential reactions add: +14 + (−30.5) = −16.5 kJ/mol. The coupling is real because ATP phosphorylates glutamate to glutamyl phosphate on the enzyme and ammonia then attacks that shared intermediate. −44.5 subtracts instead of adding. Heat from separate ATP hydrolysis cannot drive another reaction, and ATP is consumed as a reactant, not used as a catalyst.`,
  },
  [r`Intracellular/urinary buffering uses {{c1::phosphate}} ($pK_{a2}$ ~6.8); proteins buffer via {{c2::histidine}} side chains.`]: {
    question: r`Which combination would buffer best at pH 7?`,
    options: [r`H₃PO₄/H₂PO₄⁻ together with histidine side chains`, r`H₂PO₄⁻/HPO₄²⁻ together with lysine side chains`, r`H₂PO₄⁻/HPO₄²⁻ together with histidine side chains`, r`HPO₄²⁻/PO₄³⁻ together with arginine side chains`],
    correctAnswer: 2,
    explanation: r`Only groups with a pKa near 7 buffer at pH 7: the second ionization of phosphate (pKa about 6.8) and the imidazole of histidine (pKa about 6 to 7). The first ionization of phosphate has a pKa near 2 and the third near 12, so those pairs are useless at pH 7. Lysine and arginine side chains have pKa values above 10 and stay fully protonated.`,
  },
  [r`{{c1::Pyrophosphate}}-releasing reactions become irreversible because {{c2::inorganic pyrophosphatase}} destroys the PPi.`]: {
    question: r`Fatty acid + CoA + ATP → fatty acyl-CoA + AMP + PPi has a standard free energy change close to zero. What happens to this activation step in a cell that lacks inorganic pyrophosphatase?`,
    options: [r`It runs on to completion, since PPi builds up and pushes it forward`, r`It stalls near equilibrium, since PPi builds up and pushes it backward`, r`It is unaffected, since AMP and not PPi is the product that matters`, r`It stops completely, since pyrophosphatase supplies the ATP it uses`],
    correctAnswer: 1,
    explanation: r`On its own the reaction is freely reversible; it is hydrolysis of PPi to 2 Pi by pyrophosphatase that removes a product and pulls it to completion. Without the enzyme PPi accumulates and the reaction settles near equilibrium. A product building up pushes a reaction backward, not forward, PPi removal is exactly what matters, and pyrophosphatase does not make ATP.`,
  },
  [r`How does phosphocreatine buffer ATP in muscle, and what does the creatine kinase equilibrium accomplish in the first seconds of sprinting?`]: {
    question: r`A muscle biopsy is taken at rest and again 5 seconds into an all-out sprint. Creatine kinase is working normally. How do the two samples compare?`,
    options: [r`ATP is sharply lower; phosphocreatine is nearly unchanged`, r`ATP is sharply lower; phosphocreatine is also sharply lower`, r`ATP is nearly unchanged; phosphocreatine is sharply lower`, r`ATP is nearly unchanged; phosphocreatine is sharply higher`],
    correctAnswer: 2,
    explanation: r`Creatine kinase passes phosphate from phosphocreatine to ADP almost instantly, so ATP is held nearly constant while the phosphocreatine pool drains. ATP falling with phosphocreatine untouched would mean the buffer was not being used. Both falling sharply happens only after the pool is spent, and phosphocreatine rises during recovery, not during the sprint.`,
  },
  [r`Thiamine pyrophosphate (from vitamin {{c1::B1}}) serves the oxidative decarboxylases (PDH, alpha-KG DH, branched-chain), and {{c2::transketolase}} in the PPP.`]: {
    question: r`Red blood cells from a patient with chronic alcohol use show low activity of one enzyme, and the activity recovers when thiamine pyrophosphate is added to the assay. Which enzyme is it?`,
    options: [r`transketolase`, r`transaldolase`, r`pyruvate carboxylase`, r`lactate dehydrogenase`],
    correctAnswer: 0,
    explanation: r`Transketolase, in the pentose phosphate pathway, is the thiamine pyrophosphate enzyme found in red cells, which lack the mitochondrial dehydrogenase complexes, so its recovery on adding the cofactor shows thiamine deficiency. Transaldolase is its pathway partner but needs no cofactor. Pyruvate carboxylase uses biotin and lactate dehydrogenase uses NAD⁺.`,
  },
  [r`Niacin (B3) forms {{c1::$NAD^+$/$NADP^+$}}, is made from {{c2::tryptophan}}, and deficiency causes {{c3::pellagra}}.`]: {
    question: r`A child with Hartnup disease absorbs neutral amino acids such as tryptophan poorly and develops dermatitis, diarrhea and confusion. Which coenzyme shortage explains the symptoms?`,
    options: [r`FAD, which the body makes in part from tryptophan`, r`NAD⁺, which the body makes in part from tyrosine`, r`NAD⁺, which the body makes in part from tryptophan`, r`CoA, which the body makes in part from tryptophan`],
    correctAnswer: 2,
    explanation: r`The symptoms are pellagra, the niacin deficiency disease. Niacin forms NAD⁺ and NADP⁺ and can be made from tryptophan, so losing tryptophan cuts the supply. FAD comes from riboflavin and CoA from pantothenate, and neither is built from tryptophan. Tyrosine is the precursor of catecholamines, not of niacin.`,
  },
  [r`{{c1::Thymidylate synthase}} uniquely oxidizes THF to DHF, requiring {{c2::dihydrofolate reductase}} to recycle the carrier.`]: {
    question: r`Dividing cells are treated with methotrexate, an inhibitor of dihydrofolate reductase. Which change follows?`,
    options: [r`DHF accumulates and dTMP synthesis stops`, r`THF accumulates and dTMP synthesis stops`, r`DHF accumulates and dUMP synthesis stops`, r`THF accumulates and dUMP synthesis stops`],
    correctAnswer: 0,
    explanation: r`Thymidylate synthase oxidizes its folate carrier to DHF each time it converts dUMP to dTMP, and dihydrofolate reductase must reduce DHF back to THF. Blocking the reductase traps folate as DHF, so the carrier runs out and dTMP synthesis stops. THF is what becomes scarce, not what piles up, and dUMP is the substrate of the blocked step, so it is not what runs short.`,
  },
  [r`In ATP, the alpha phosphate-ribose link is a {{c1::phosphoester}}; the beta-gamma links are high-energy {{c2::phosphoanhydrides}}.`]: {
    question: r`A phosphatase hydrolyzes AMP to adenosine and Pi. How does the standard free energy released compare with that of ATP → ADP + Pi (about −30.5 kJ/mol)?`,
    options: [r`About the same, because the bond cleaved is a phosphoanhydride`, r`About half as much, because the bond cleaved is a phosphoester`, r`About twice as much, because the bond cleaved is a phosphoester`, r`About half as much, because the bond cleaved is a phosphoanhydride`],
    correctAnswer: 1,
    explanation: r`The alpha phosphate is joined to ribose by a phosphoester, worth only about −14 kJ/mol, roughly half of a phosphoanhydride. Only the alpha-beta and beta-gamma links are anhydrides, so calling the AMP bond an anhydride is wrong whatever energy is attached. A phosphoester releases less energy than an anhydride, not more.`,
  },
  [r`Cells hold the {{c1::$NAD^+$/NADH}} couple oxidized to drive catabolism, but keep {{c2::NADPH/$NADP^+$}} reduced to drive biosynthesis.`]: {
    question: r`In the cytosol of a liver cell, one enzyme reduces a keto group during fatty acid synthesis and another oxidizes an alcohol group during fuel breakdown. Which coenzymes are these two enzymes expected to use?`,
    options: [r`NADH for the biosynthetic reduction; NADP⁺ for the catabolic oxidation`, r`NADPH for the biosynthetic reduction; NAD⁺ for the catabolic oxidation`, r`NADPH for the biosynthetic reduction; NADP⁺ for the catabolic oxidation`, r`NADH for the biosynthetic reduction; NAD⁺ for the catabolic oxidation`],
    correctAnswer: 1,
    explanation: r`The cell keeps the NADPH/NADP⁺ pool mostly reduced so that NADPH can donate electrons in biosynthesis, and keeps the NAD⁺/NADH pool mostly oxidized so that NAD⁺ can accept electrons in catabolism. Using NADH for synthesis or NADP⁺ for breakdown assigns each job to the pool that is poised the wrong way.`,
  },
  [r`In the well-fed state, which pathways does the high insulin-to-glucagon ratio switch ON in liver, and through what shared second-messenger change?`]: {
    question: r`One hour after a large carbohydrate meal, what are the cAMP level in the liver and the state of glycogen synthase and acetyl-CoA carboxylase?`,
    options: [r`cAMP is low; both enzymes are phosphorylated and active`, r`cAMP is high; both enzymes are phosphorylated and inactive`, r`cAMP is high; both enzymes are dephosphorylated and active`, r`cAMP is low; both enzymes are dephosphorylated and active`],
    correctAnswer: 3,
    explanation: r`A high insulin-to-glucagon ratio lowers cAMP and activates phosphatases such as PP1, so hepatic enzymes are dephosphorylated, and for these two storage enzymes dephosphorylated means active. Phosphorylated and active mixes up the states, since phosphorylation inactivates both. High cAMP is the fasting signal from glucagon, when both enzymes are phosphorylated and switched off.`,
  },
  [r`Rank the phosphoryl-transfer potentials: PEP, 1,3-BPG, phosphocreatine, ATP, glucose 6-phosphate. Why is ATP's middle position functionally essential?`]: {
    question: r`Phosphoryl-transfer potential runs PEP > 1,3-bisphosphoglycerate > phosphocreatine > ATP > glucose 6-phosphate (G6P). Which transfer is favorable under standard conditions?`,
    options: [r`PEP + ADP → pyruvate + ATP`, r`G6P + ADP → glucose + ATP`, r`pyruvate + ATP → PEP + ADP`, r`creatine + ATP → phosphocreatine + ADP`],
    correctAnswer: 0,
    explanation: r`A phosphoryl group moves spontaneously from a compound higher on the scale to one lower, and PEP sits above ATP, so PEP can phosphorylate ADP. G6P sits below ATP and cannot make ATP from ADP. Making PEP or phosphocreatine from ATP moves the group uphill, which is unfavorable under standard conditions.`,
  },
  [r`Which enzyme classes use FAD/FMN (riboflavin), and why can flavins participate in reactions NAD cannot?`]: {
    question: r`An enzyme must remove two electrons together from its substrate and then hand them one at a time to an iron-sulfur cluster. Which cofactor suits this job, and why?`,
    options: [r`NAD⁺, because it can hold a single electron as a semiquinone`, r`FAD, because it can hold a single electron as a semiquinone`, r`NAD⁺, because it carries electrons only in pairs as a hydride`, r`FAD, because it carries electrons only in pairs as a hydride`],
    correctAnswer: 1,
    explanation: r`Flavins can accept or give up electrons one at a time through a stable semiquinone state, so they bridge two-electron donors to one-electron carriers such as iron-sulfur clusters. NAD⁺ has no semiquinone and handles only hydride transfers, which is why it cannot do the single-electron step. Describing FAD as limited to hydride transfer gives it the restriction that belongs to NAD⁺.`,
  },
  [r`Pantothenate (B5) is built into which two acyl-carrying structures, and what is the actual reactive group?`]: {
    question: r`A chemist makes an analog of coenzyme A in which the terminal thiol is replaced by a hydroxyl group, so acetate is carried as an oxygen ester. How does the acyl group's reactivity change, and why?`,
    options: [r`It is more reactive: oxygen esters are less stabilized by resonance`, r`It is unchanged: the adenine ring of the coenzyme is what reacts`, r`It is unchanged: the phosphate groups of the coenzyme are what react`, r`It is less reactive: oxygen esters are more stabilized by resonance`],
    correctAnswer: 3,
    explanation: r`The working group of coenzyme A is its thiol, and a thioester has poor resonance stabilization because sulfur overlaps badly with the carbonyl, which keeps the acyl group activated. An oxygen ester is better stabilized by resonance, so the acyl group becomes less reactive. The adenine and phosphate parts are handles for enzyme binding and do not carry the acyl group.`,
  },
  [r`PLP (B6) forms a {{c1::Schiff base}} with substrates for {{c2::transamination}}/decarboxylation and assists {{c3::glycogen phosphorylase}}.`]: {
    question: r`Alanine aminotransferase activity is low in a liver extract from a vitamin B6-deficient animal. Which cofactor restores it, and what does that cofactor form with alanine?`,
    options: [r`pyridoxal phosphate, forming a Schiff base with the amino group`, r`pyridoxal phosphate, forming a thioester with the carboxyl group`, r`thiamine pyrophosphate, forming a Schiff base with the amino group`, r`thiamine pyrophosphate, forming a thioester with the carboxyl group`],
    correctAnswer: 0,
    explanation: r`Transaminases use pyridoxal phosphate, the coenzyme from vitamin B6, whose aldehyde forms a Schiff base (imine) with the amino group of the amino acid. Thioesters are the chemistry of coenzyme A and lipoamide, not of pyridoxal phosphate. Thiamine pyrophosphate comes from vitamin B1 and serves decarboxylases and transketolase.`,
  },
  [r`Biotin (B7) serves the three major {{c1::carboxylases}} and is bound by {{c2::avidin}} in raw egg white.`]: {
    question: r`A bodybuilder who eats large amounts of raw egg white every day develops a deficiency because avidin binds one vitamin in the gut. Which reaction is most directly impaired?`,
    options: [r`pyruvate + NAD⁺ → acetyl-CoA + CO₂`, r`pyruvate + CO₂ + ATP → oxaloacetate`, r`oxaloacetate + GTP → PEP + CO₂`, r`pyruvate + NADH → lactate + NAD⁺`],
    correctAnswer: 1,
    explanation: r`Avidin binds biotin, the coenzyme of the ATP-dependent carboxylases, so pyruvate carboxylase, which adds CO₂ to pyruvate to make oxaloacetate, is impaired. Pyruvate to acetyl-CoA is a decarboxylation by pyruvate dehydrogenase and needs thiamine, not biotin. PEPCK also removes CO₂ and uses GTP, and lactate dehydrogenase needs only NADH.`,
  },
  [r`List the five cofactors of the pyruvate dehydrogenase complex and the vitamin behind each.`]: {
    question: r`A patient is deficient in riboflavin only. What is the most direct effect on the pyruvate dehydrogenase complex?`,
    options: [r`FAD is short, so electrons cannot leave reduced lipoamide`, r`TPP is short, so pyruvate cannot be decarboxylated at all`, r`CoA is short, so the acetyl group has no final acceptor`, r`NAD⁺ is short, so electrons cannot leave the reduced FAD`],
    correctAnswer: 0,
    explanation: r`Riboflavin is vitamin B2, the precursor of FAD, which in the complex takes electrons from reduced lipoamide before passing them to NAD⁺. Thiamine pyrophosphate comes from B1, coenzyme A from B5 and NAD⁺ from B3, so those three cofactors are still available when only riboflavin is missing.`,
  },
  [r`A nucleoside is base + sugar joined by a beta-{{c1::N-glycosidic}} bond; adding phosphate at the {{c2::5'}} carbon makes a nucleotide.`]: {
    question: r`An enzyme cleaves the bond between N1 of cytosine and C1' of ribose in cytidine 5'-monophosphate (CMP). Which bond is broken, and what are the products?`,
    options: [r`N-glycosidic bond; cytosine and ribose 5-phosphate`, r`phosphoester bond; cytidine and inorganic phosphate`, r`N-glycosidic bond; cytidine and inorganic phosphate`, r`phosphoester bond; cytosine and ribose 5-phosphate`],
    correctAnswer: 0,
    explanation: r`The base is joined to C1' of the sugar by a beta-N-glycosidic bond, and breaking it frees the base, cytosine, leaving the sugar with its 5' phosphate still attached. Cytidine and phosphate would be the products of cutting the phosphoester at the 5' carbon instead. The other two options pair a bond name with the products of the other cleavage.`,
  },
  [r`Beyond translation, name three distinct metabolic or signaling roles of GTP specifically.`]: {
    question: r`A liver cell has plenty of ATP but has run out of GTP. Which of these reactions is directly blocked?`,
    options: [r`glucose to glucose 6-phosphate, by glucokinase`, r`pyruvate to oxaloacetate, by pyruvate carboxylase`, r`oxaloacetate to phosphoenolpyruvate, by PEPCK`, r`fructose 6-phosphate to the 1,6-bisphosphate, by PFK-1`],
    correctAnswer: 2,
    explanation: r`PEPCK uses GTP, not ATP, as its phosphoryl donor when it converts oxaloacetate to phosphoenolpyruvate in gluconeogenesis. Glucokinase and PFK-1 are ATP-dependent kinases, and pyruvate carboxylase uses ATP with biotin to add CO₂, so all three still run when only GTP is missing.`,
  },
  [r`Carrier code: {{c1::UDP}}-sugars for glycogen, {{c2::CDP}} intermediates for phospholipids, {{c3::SAM}} (from ATP) for methylation.`]: {
    question: r`A liver cell needs to add a glucose unit to glycogen and to activate a lipid intermediate for phospholipid synthesis. Which nucleotides supply the activating carriers?`,
    options: [r`CTP for the glucose unit and UTP for the lipid unit`, r`UTP for the glucose unit and CTP for the lipid unit`, r`GTP for the glucose unit and CTP for the lipid unit`, r`UTP for the glucose unit and GTP for the lipid unit`],
    correctAnswer: 1,
    explanation: r`Sugars are activated on uridine nucleotides (UDP-glucose for glycogen) and phospholipid intermediates on cytidine nucleotides (CDP-diacylglycerol, CDP-choline). Swapping UTP and CTP reverses the code. GTP is the carrier for neither of these: its jobs are in translation, G proteins, PEPCK and the succinyl-CoA synthetase step.`,
  },
  [r`Timescales: {{c1::allosteric}} control = milliseconds, {{c2::covalent modification}} = seconds-minutes, {{c3::transcription}} = hours.`]: {
    question: r`A hormone is added to cultured liver cells. The activity of enzyme E does not change during the first 30 minutes, then rises steadily between 2 and 8 hours. Which mechanism best fits this time course?`,
    options: [r`allosteric activation, reshaping the existing enzyme E`, r`phosphorylation, modifying the existing enzyme E`, r`substrate binding, saturating the existing enzyme E`, r`transcriptional induction, raising the amount of enzyme E`],
    correctAnswer: 3,
    explanation: r`A response that takes hours to appear points to transcription and synthesis of new enzyme. Allosteric effects and substrate binding act in milliseconds, so they would show at once. Covalent modification such as phosphorylation acts within seconds to minutes, so it would be visible well inside the first 30 minutes.`,
  },
  [r`Paired opposing reactions like PFK-1/FBPase-1 seem wasteful. What regulatory advantage justifies substrate cycling?`]: {
    question: r`In a substrate cycle, the forward enzyme runs at 100 units and the reverse enzyme at 90 units, giving a net forward flux of 10 units. A regulator raises the forward enzyme's activity by 10% and leaves the reverse enzyme alone. By how much does net flux change?`,
    options: [r`10%, from 10 to 11 units`, r`10%, from 100 to 110 units`, r`20%, from 10 to 12 units`, r`100%, from 10 to 20 units`],
    correctAnswer: 3,
    explanation: r`The forward rate becomes 110 units, so net flux is 110 − 90 = 20 units, double the original 10: a 10% change in one enzyme gives a 100% change in net flux, which is the amplification that justifies the cycle. A 10% rise to 11 applies the change to net flux directly. Quoting 100 to 110 gives the forward rate, not the net flux, and 12 has no basis in the numbers.`,
  },
  [r`Give three examples of compartmentalization acting as a regulatory mechanism in metabolism.`]: {
    question: r`A lysosome leaks a small amount of its acid hydrolases into the cytosol, where the pH is 7.2. How active are the leaked enzymes, and why?`,
    options: [r`Fully active, since they need the neutral pH of the cytosol`, r`Nearly inactive, since they need the acidic pH of the lysosome`, r`Nearly inactive, since they need the ATP found in lysosomes`, r`Fully active, since hydrolases work the same at any pH value`],
    correctAnswer: 1,
    explanation: r`Lysosomal hydrolases have an acidic pH optimum near 5, so keeping them in an acidic compartment is itself a control: outside it, at pH 7.2, they are largely inactive and the cytosol is protected. They are not tuned to neutral pH, hydrolysis needs no ATP, and enzyme activity depends strongly on pH.`,
  },
  [r`Active AMPK {{c1::inhibits}} ACC and HMG-CoA reductase while {{c2::stimulating}} glucose uptake and fatty acid oxidation.`]: {
    question: r`Cultured muscle cells are treated with a drug that activates AMPK. Which pair of changes is expected?`,
    options: [r`glucose uptake falls and cholesterol synthesis rises`, r`glucose uptake rises and cholesterol synthesis falls`, r`glucose uptake rises and cholesterol synthesis rises`, r`glucose uptake falls and cholesterol synthesis falls`],
    correctAnswer: 1,
    explanation: r`AMPK is the low-fuel switch: it stimulates ATP-producing processes such as glucose uptake and fatty acid oxidation and inhibits ATP-consuming synthesis, including HMG-CoA reductase, the rate-limiting enzyme of cholesterol synthesis. The other options either reverse both effects or have AMPK driving uptake and synthesis in the same direction.`,
  },
  [r`Fasting: liver glycogen lasts ~{{c1::24 h}}; gluconeogenesis then dominates; by ~{{c2::3 days}} ketones spare muscle {{c3::protein}}.`]: {
    question: r`Urinary nitrogen, a marker of body protein breakdown, is measured in a person on day 2 and again on day 20 of a fast. How does it change, and why?`,
    options: [r`It rises, because the brain now burns ketones and needs more glucose`, r`It falls, because the brain now burns ketones and needs less glucose`, r`It rises, because liver glycogen has only just now been used up`, r`It falls, because liver glycogen has been rebuilt from fatty acids`],
    correctAnswer: 1,
    explanation: r`Early in a fast, gluconeogenesis draws heavily on amino acids from muscle. After several days the brain takes much of its fuel as ketone bodies, so glucose demand drops and protein breakdown falls with it. Ketone use lowers the need for glucose, not raises it. Liver glycogen is gone after about a day, and fatty acids cannot be converted into glucose or glycogen.`,
  },
  [r`How do cortisol and epinephrine divide the counter-regulatory labor against hypoglycemia?`]: {
    question: r`Two hormones are given to hypoglycemic animals. Hormone X raises blood glucose within a minute, even when a transcription inhibitor is present. Hormone Y takes several hours and has no effect when transcription is blocked. Which identification fits?`,
    options: [r`X is cortisol and Y is epinephrine`, r`X is insulin and Y is cortisol`, r`X is epinephrine and Y is cortisol`, r`X is cortisol and Y is glucagon`],
    correctAnswer: 2,
    explanation: r`Epinephrine is the fast lever: it acts in seconds through cAMP to trigger glycogenolysis, with no new gene expression needed. Cortisol is the slow lever, raising glucose over hours by inducing enzymes such as PEPCK, so it depends on transcription. Reversing the two swaps their speeds. Insulin lowers blood glucose, and glucagon acts quickly through cAMP.`,
  },
  [r`ATP hydrolysis is strongly exergonic due to relief of {{c1::charge repulsion}}, {{c2::resonance}} stabilization of $P_i$, and greater solvation of products.`]: {
    question: r`At very low pH the oxygen atoms of ATP's phosphate chain pick up protons and lose most of their negative charge. How would this be expected to change the free energy of ATP hydrolysis?`,
    options: [r`More exergonic, because there is less charge repulsion to relieve`, r`Less exergonic, because the phosphate bonds have become stronger`, r`Less exergonic, because there is less charge repulsion to relieve`, r`Unchanged, because only the bond strength sets the energy released`],
    correctAnswer: 2,
    explanation: r`Much of the energy of ATP hydrolysis comes from separating closely packed negative charges on the triphosphate, so removing those charges removes part of the driving force and hydrolysis becomes less exergonic. Less repulsion cannot make it more exergonic. The explanations based on bond strength miss the point: the energy comes from the products being more stable, through relief of repulsion, resonance and solvation.`,
  },
  [r`Why are metabolic control points always the far-from-equilibrium reactions rather than the near-equilibrium ones?`]: {
    question: r`In a pathway, step X runs with $\Delta G$ = −0.5 kJ/mol in the cell and step Y runs with $\Delta G$ = −22 kJ/mol. A drug that halves the activity of one enzyme is available. Inhibiting which step reduces pathway flux more, and why?`,
    options: [r`Step Y, because it is far from equilibrium and acts as a one-way valve`, r`Step X, because it is near equilibrium and acts as a one-way valve`, r`Step X, because its small ΔG shows its enzyme is already saturated`, r`Step Y, because its large ΔG shows the reaction is near equilibrium`],
    correctAnswer: 0,
    explanation: r`A step with a large negative ΔG is far from equilibrium, so its enzyme activity limits the flux and inhibiting it slows the whole pathway. A near-equilibrium step such as X runs both ways by mass action and still keeps up when its enzyme is partly inhibited, so it is not a valve. A small ΔG says nothing about saturation, and a large ΔG means far from equilibrium, not near it.`,
  },
  [r`Convert a blood glucose of 90 mg/dL to millimolar, given a molar mass of 180 g/mol.`]: {
    question: r`A blood lactate level is reported as 18 mg/dL. Lactate has a molar mass of 90 g/mol. What is the concentration in millimolar?`,
    options: [r`2 mM`, r`0.2 mM`, r`20 mM`, r`5 mM`],
    correctAnswer: 0,
    explanation: r`18 mg/dL is 180 mg/L, or 0.18 g/L, and 0.18 g/L ÷ 90 g/mol = 0.002 M = 2 mM. The answer 0.2 mM forgets that a litre is ten decilitres, and 20 mM multiplies by ten twice. The answer 5 mM divides the molar mass by the mass, 90 ÷ 18, instead of the other way round.`,
  },
  [r`What can a pulse-chase experiment establish that a single labeled timepoint cannot?`]: {
    question: r`Cells are given radioactive leucine for 3 minutes and then switched to unlabeled leucine. Label in compartment A peaks at 5 minutes and then falls. Label in B peaks at 20 minutes and then falls. Label in C appears after 30 minutes and stays high. What does this show?`,
    options: [r`The order is C, then B, then A, and A is the end point`, r`The order is A, then B, then C, and A is the end point`, r`The order is B, then A, then C, and C is the end point`, r`The order is A, then B, then C, and C is the end point`],
    correctAnswer: 3,
    explanation: r`In a pulse-chase the label passes through intermediates in order: it peaks first in the earliest station and last in the final one. A and B rise and then fall, so they are intermediates, with A before B, while C keeps its label, so it is the end point. Reversing the order ignores the timing, and A cannot be the end point because its label leaves.`,
  },
  [r`Why does a hormone cascade amplify its signal so powerfully?`]: {
    question: r`In a signaling cascade, one hormone-bound receptor activates 10 G proteins. Each G protein activates one adenylyl cyclase, and each cyclase makes 100 cAMP molecules. How many cAMP molecules result from one bound hormone, and why?`,
    options: [r`110, because the gains of the stages are added`, r`100, because only the final stage sets the gain`, r`1,000, because the gains of the stages multiply`, r`10, because only the first stage sets the gain`],
    correctAnswer: 2,
    explanation: r`Each active element is a catalyst that produces many copies of the next, so stage gains multiply: 10 × 1 × 100 = 1,000 cAMP. Adding the gains gives 110 and misses the point of a cascade. Counting only the last stage or only the first stage ignores the amplification that every catalytic step contributes.`,
  },
  [r`Rank the noncovalent interactions that stabilize a folded protein from strongest to weakest.`]: {
    question: r`Considering one interaction at a time, which of these contributes the least energy to holding a folded protein together?`,
    options: [r`a salt bridge between lysine and aspartate side chains`, r`a dispersion contact between two leucine side chains`, r`a hydrogen bond between serine and threonine side chains`, r`a disulfide bond between two cysteine side chains`],
    correctAnswer: 1,
    explanation: r`London dispersion contacts between nonpolar groups are the weakest, near 1 kJ/mol each, and matter only because there are so many of them. A salt bridge and a hydrogen bond are each worth roughly 4 to 20 kJ/mol. A disulfide is a covalent bond, hundreds of kJ/mol, and is by far the strongest on the list.`,
  },
  [r`Order-of-magnitude values: cellular ATP about {{c1::5}} mM, cytosolic free $Ca^{2+}$ about {{c2::100}} nM, blood glucose about 5 mM.`]: {
    question: r`A resting cell has ATP and cytosolic free Ca²⁺ at their typical concentrations. Roughly how many ATP molecules does the cytosol hold for every free Ca²⁺ ion?`,
    options: [r`about 50`, r`about 50,000`, r`about 500`, r`about 5,000,000`],
    correctAnswer: 1,
    explanation: r`ATP is about 5 mM and resting cytosolic free Ca²⁺ about 100 nM, so the ratio is 5 × 10⁻³ M ÷ 1 × 10⁻⁷ M = 50,000. A ratio of 50 or 500 would need calcium in the micromolar range, far above its resting level, and 5,000,000 would need calcium near 1 nM. The very low resting calcium level is what makes it such a high-contrast messenger.`,
  },
  [r`Receptor tyrosine kinases signal by {{c1::dimerizing and autophosphorylating}}, whereas GPCRs work through {{c2::G proteins}} and diffusible second messengers.`]: {
    question: r`An antibody is designed that pulls two epidermal growth factor receptors (receptor tyrosine kinases) together on the cell surface, with no growth factor present. What is the expected result?`,
    options: [r`Signaling turns on, since paired receptors each activate a G protein`, r`Signaling stays off, since only cAMP can switch this receptor on`, r`Signaling stays off, since paired receptors cannot bind any ATP`, r`Signaling turns on, since paired receptors phosphorylate each other`],
    correctAnswer: 3,
    explanation: r`Receptor tyrosine kinases are activated by dimerization: once two receptors are brought together their kinase domains phosphorylate each other's tyrosines, whatever brought them together. G proteins and cAMP belong to GPCR signaling, not to this receptor class. Pairing does not block ATP binding; it is what lets the kinase domains work.`,
  },
  [r`GPCR outputs: $G_s$ {{c1::raises}} cAMP, $G_i$ lowers it, and $G_q$ activates phospholipase C to generate {{c2::IP3 and DAG}}.`]: {
    question: r`A hormone binds a receptor coupled to $G_q$ on a smooth muscle cell. Which sequence of events follows?`,
    options: [r`Phospholipase C is activated; IP3 releases Ca²⁺ from the ER and DAG activates PKC`, r`Phospholipase C is activated; DAG releases Ca²⁺ from the ER and IP3 activates PKC`, r`Adenylyl cyclase is activated; cAMP rises and protein kinase A is switched on`, r`Adenylyl cyclase is inhibited; cAMP falls and protein kinase A is switched off`],
    correctAnswer: 0,
    explanation: r`Gq activates phospholipase C, which makes two messengers: soluble IP3 opens calcium channels in the endoplasmic reticulum, and DAG stays in the membrane and activates protein kinase C. Swapping the roles of IP3 and DAG is the common slip. Activating adenylyl cyclase is the Gs pathway and inhibiting it is the Gi pathway.`,
  },
  [r`One pH unit above a group's $pK_a$, the deprotonated-to-protonated ratio is {{c1::10 to 1}}; two units above, it is {{c2::100 to 1}}.`]: {
    question: r`A carboxyl group has a $pK_a$ of 4.0. In a solution at pH 6.0, about what fraction of these groups is still protonated?`,
    options: [r`about 10%`, r`about 99%`, r`about 1%`, r`about 50%`],
    correctAnswer: 2,
    explanation: r`Two pH units above the pKa the deprotonated-to-protonated ratio is 100 to 1, so about 1 group in 101, roughly 1%, keeps its proton. About 10% is the answer for one unit above the pKa. About 99% is the deprotonated fraction, not the protonated one, and 50% applies only when pH equals pKa.`,
  },
  [r`Humans digest the {{c1::alpha}}-1,4 linkages of starch but not the {{c2::beta}}-1,4 linkages of cellulose.`]: {
    question: r`A glucose polymer joined entirely by beta-1,4 linkages is added to a human diet. What happens to it in the small intestine?`,
    options: [r`It is digested to glucose, since human enzymes cleave beta-1,4 but not alpha-1,4 links`, r`It passes undigested, since human enzymes cleave no links between glucose units`, r`It passes undigested, since human enzymes cleave alpha-1,4 but not beta-1,4 links`, r`It is digested to glucose, since human enzymes cleave any link between glucose units`],
    correctAnswer: 2,
    explanation: r`Amylase and the brush-border enzymes are stereospecific for alpha linkages, and humans make no enzyme for beta-1,4 links between glucose units, so the polymer behaves like cellulose and passes through as fiber. Saying humans cleave beta but not alpha links reverses the specificity. Humans do digest the alpha-1,4 links of starch, so the two blanket statements are also wrong.`,
  },
  [r`The {{c1::anomeric}} carbon is the former carbonyl carbon, and in D-glucopyranose the {{c2::beta}} anomer places its hydroxyl equatorial.`]: {
    question: r`Pure alpha-D-glucopyranose is dissolved in water. After several hours the solution is about 64% beta anomer and 36% alpha anomer. Why is the beta anomer favored?`,
    options: [r`its C1 hydroxyl is equatorial, which is less crowded`, r`its C1 hydroxyl is axial, which is less crowded`, r`its C4 hydroxyl is equatorial, which is less crowded`, r`its C1 hydroxyl is axial, which is more reactive`],
    correctAnswer: 0,
    explanation: r`Anomers differ only at C1, the anomeric carbon, and in the beta form of D-glucopyranose that hydroxyl is equatorial, the less crowded position, so beta is more stable and predominates after mutarotation. The axial C1 hydroxyl belongs to the alpha anomer and is the more crowded position. C4 is the same in both anomers, so it cannot explain the difference.`,
  },
  [r`Glucose and galactose are epimers at carbon {{c1::4}}; glucose and mannose are epimers at carbon {{c2::2}}.`]: {
    question: r`An enzyme inverts the configuration at carbon 2 of D-glucose and changes nothing else. What is the product?`,
    options: [r`D-mannose`, r`D-galactose`, r`D-fructose`, r`L-glucose`],
    correctAnswer: 0,
    explanation: r`Glucose and mannose are epimers at carbon 2, so inverting only that center gives D-mannose. D-galactose is the carbon 4 epimer. D-fructose is a ketose, a structural isomer and not an epimer, and L-glucose is the mirror image, which would need every stereocenter inverted.`,
  },
  [r`Arterial pH is held at {{c1::7.35-7.45}}; the lungs adjust {{c2::$CO_2$}} within minutes while the kidneys adjust bicarbonate over {{c3::days}}.`]: {
    question: r`A patient breathes too slowly for 20 minutes after an opioid overdose. Which set of arterial blood findings is expected at that point?`,
    options: [r`pH below 7.35 with high CO₂; bicarbonate already fully raised by the kidneys`, r`pH above 7.45 with low CO₂; bicarbonate not yet adjusted by the kidneys`, r`pH above 7.45 with high CO₂; bicarbonate already fully raised by the kidneys`, r`pH below 7.35 with high CO₂; bicarbonate not yet adjusted by the kidneys`],
    correctAnswer: 3,
    explanation: r`Hypoventilation retains CO₂, which pushes pH below the normal 7.35 to 7.45 range: respiratory acidosis. The lungs change CO₂ within minutes, but the kidneys need days to adjust bicarbonate, so after 20 minutes there is no renal compensation. Low CO₂ with high pH describes hyperventilation, and retained CO₂ cannot raise pH above 7.45.`,
  },
  [r`How can you tell by inspection whether a carbon was oxidized in a metabolic step?`]: {
    question: r`An enzyme converts 3-hydroxybutyrate, whose carbon 3 carries an OH and an H, into acetoacetate, whose carbon 3 is a C=O. What happened to carbon 3 and to the enzyme's cofactor?`,
    options: [r`C3 was oxidized (it lost a C-H bond), and NAD⁺ was reduced to NADH`, r`C3 was reduced (it lost a C-H bond), and NADH was oxidized to NAD⁺`, r`C3 was oxidized (it gained a C-H bond), and NADH was oxidized to NAD⁺`, r`C3 was reduced (it gained a C-O bond), and NAD⁺ was reduced to NADH`],
    correctAnswer: 0,
    explanation: r`Going from an alcohol carbon to a carbonyl carbon trades a C-H bond for a second C-O bond, which is oxidation, and the electrons removed are accepted by NAD⁺, making NADH. Losing a C-H bond is never reduction, and the carbon did not gain a C-H bond. Gaining a C-O bond is also oxidation, so calling it reduction has the definition backward.`,
  },
  [r`Why does a more {{c1::reduced}} fuel release more energy per carbon when fully oxidized?`]: {
    question: r`One mole of each of these two-carbon compounds is burned completely to CO₂ and water. Which releases the most energy?`,
    options: [r`ethanol, CH₃CH₂OH`, r`ethane, CH₃CH₃`, r`acetaldehyde, CH₃CHO`, r`acetic acid, CH₃COOH`],
    correctAnswer: 1,
    explanation: r`The more reduced the carbons, the more C-H bonds there are to give electrons to oxygen, so the fully reduced ethane releases the most energy. Ethanol, acetaldehyde and acetic acid are progressively more oxidized, each already holding more bonds to oxygen, so each releases less than the one before it.`,
  },
  [r`At pH 7.4, carboxylic acids are {{c1::deprotonated}} and aliphatic amines are {{c2::protonated}}, so both carry charge and cross membranes poorly.`]: {
    question: r`Drug 1 has a carboxylic acid group with a pKa of 4, and drug 2 has an aliphatic amine group with a pKa of 10. In blood at pH 7.4, what are their main forms, and how well do those forms cross a lipid bilayer by simple diffusion?`,
    options: [r`The acid is anionic and the amine is cationic, so both cross poorly`, r`The acid is neutral and the amine is neutral, so both cross readily`, r`The acid is anionic and the amine is neutral, so only the amine crosses`, r`The acid is neutral and the amine is cationic, so only the acid crosses`],
    correctAnswer: 0,
    explanation: r`pH 7.4 is far above the acid's pKa, so it is deprotonated to COO⁻, and far below the amine's pKa, so it is protonated to NH₃⁺. Both drugs are charged, and only neutral molecules diffuse freely across a bilayer. The other options leave the acid protonated or the amine unprotonated, which would need a pH below 4 or above 10.`,
  },
  [r`Why do fatty acid salts assemble into {{c1::micelles}} while phospholipids assemble into {{c2::bilayers}}?`]: {
    question: r`A phospholipase removes one of the two fatty acyl tails from every phospholipid in a vesicle, leaving lipids with one tail and a large head group. What do these lipids tend to form in water, and why?`,
    options: [r`Bilayers, because a one-tailed lipid is cylindrical and packs into a sheet`, r`Micelles, because a one-tailed lipid is cylindrical and packs into a sheet`, r`Bilayers, because a one-tailed lipid is wedge-shaped and packs into a sphere`, r`Micelles, because a one-tailed lipid is wedge-shaped and packs into a sphere`],
    correctAnswer: 3,
    explanation: r`Shape decides the assembly: a single tail under a large head makes a wedge that packs into a sphere with the tails inside, which is a micelle, just as fatty acid salts do. Two tails make a roughly cylindrical lipid that tiles into a flat bilayer. The other options either give the one-tailed lipid the wrong shape or attach the wrong structure to that shape.`,
  },
  [r`Biological amino acids are almost all {{c1::L}} and biological sugars almost all {{c2::D}}, assigned from the chiral carbon farthest from the carbonyl.`]: {
    question: r`An aldohexose is drawn as a Fischer projection with the aldehyde at the top. The hydroxyl on C2 points left and the hydroxyl on C5 points right. How is the sugar designated, and why?`,
    options: [r`L, because the C2 hydroxyl is on the left`, r`D, because the C2 hydroxyl is on the left`, r`L, because the C5 hydroxyl is on the right`, r`D, because the C5 hydroxyl is on the right`],
    correctAnswer: 3,
    explanation: r`D or L is assigned from the chiral carbon farthest from the carbonyl, which is C5 in an aldohexose, and a hydroxyl on the right there means D. C2 is the chiral carbon nearest the carbonyl and plays no part in the label, so both options that reason from C2 use the wrong carbon. A right-hand hydroxyl at C5 means D, not L.`,
  },
  [r`A reducing sugar has a free {{c1::anomeric}} carbon and therefore gives a positive {{c2::Benedict's}} or Tollens test.`]: {
    question: r`Trehalose is a disaccharide in which two glucose units are joined through the anomeric carbon of one and the anomeric carbon of the other. What result does it give in Benedict's test, and why?`,
    options: [r`Positive, because both anomeric carbons are tied up in the glycosidic bond`, r`Negative, because both anomeric carbons are tied up in the glycosidic bond`, r`Positive, because every disaccharide of glucose keeps a free aldehyde`, r`Negative, because glucose itself is not a reducing monosaccharide`],
    correctAnswer: 1,
    explanation: r`A sugar reduces Benedict's reagent only if it has a free anomeric carbon that can open to an aldehyde. In trehalose both anomeric carbons are locked in the linkage, as in sucrose, so the test is negative. Locked anomeric carbons cannot give a positive test, maltose shows that only some glucose disaccharides keep a free one, and glucose itself is a reducing sugar.`,
  },
}
